<?php $pageTitle='Add task'; $activePage='tasks'; require_once __DIR__.'/../includes/header.php'; require_permission('manage_tasks'); $projects=$pdo->query('SELECT id,name FROM projects WHERE status NOT IN ("Completed","Cancelled") ORDER BY name')->fetchAll(); $users=$pdo->query('SELECT id,name FROM users WHERE status="active" ORDER BY name')->fetchAll(); if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf']??null)){flash('danger','Security token expired.');}else{$statement=$pdo->prepare('INSERT INTO tasks(project_id,assigned_to,title,description,priority,status,start_date,due_date,estimated_hours) VALUES (?,?,?,?,?,?,?,?,?)');$statement->execute([(int)$_POST['project_id'],(int)$_POST['assigned_to']?:null,trim($_POST['title']),trim($_POST['description']),$_POST['priority'],$_POST['status'],$_POST['start_date'],$_POST['due_date'],(float)$_POST['estimated_hours']]);$id=(int)$pdo->lastInsertId();record_activity('Created task','task',$id);flash('success','Task created.');redirect('tasks/');}} ?><div class="mb-4"><span class="section-kicker">Execution</span><h2 class="mt-2">Add a task</h2></div><form method="post" class="panel form-panel"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-12"><label class="form-label">Task title<input name="title" class="form-control" required placeholder="What needs to move forward?"></label></div><div class="col-md-6"><label class="form-label">Project<select name="project_id" class="form-select" required><option value="">Choose project</option><?php foreach($projects as $project): ?><option value="<?= $project['id'] ?>"><?= e($project['name']) ?></option><?php endforeach; ?></select></label></div><div class="col-md-6"><label class="form-label">Assigned user<select name="assigned_to" class="form-select"><option value="">Unassigned</option><?php foreach($users as $user): ?><option value="<?= $user['id'] ?>"><?= e($user['name']) ?></option><?php endforeach; ?></select></label></div><div class="col-md-4"><label class="form-label">Priority<select name="priority" class="form-select"><?php foreach(['Low','Medium','High','Critical'] as $value): ?><option><?= e($value) ?></option><?php endforeach; ?></select></label></div><div class="col-md-4"><label class="form-label">Status<select name="status" class="form-select"><?php foreach(['Backlog','To Do','In Progress','Code Review','Testing','Done'] as $value): ?><option><?= e($value) ?></option><?php endforeach; ?></select></label></div><div class="col-md-4"><label class="form-label">Estimated hours<input name="estimated_hours" type="number" step="0.5" class="form-control" value="0"></label></div><div class="col-md-6"><label class="form-label">Start date<input name="start_date" type="date" class="form-control" required></label></div><div class="col-md-6"><label class="form-label">Due date<input name="due_date" type="date" class="form-control" required></label></div><div class="col-12"><label class="form-label">Description<textarea name="description" class="form-control" rows="5"></textarea></label></div></div><div class="mt-4 d-flex gap-2"><button class="btn btn-primary">Create task</button><a href="<?= url('tasks/') ?>" class="btn btn-light">Cancel</a></div></form><?php require_once __DIR__.'/../includes/footer.php'; ?>
